"""Code-only three-cohort Colab runner. No LMEv2 job and no stop-old action."""
import base64
import hashlib
import importlib.util
import io
import json
import os
from pathlib import Path
import sys
import zipfile

CODE_PAYLOAD = ""
CODE_SHA = "dedb21cecb855b93ba1a25129ff72a46a2ae13c6ed53059a0df4e00461537ede"


def module(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    result = importlib.util.module_from_spec(spec)
    sys.modules[name] = result
    spec.loader.exec_module(result)
    return result


def unpack():
    raw = base64.b64decode(CODE_PAYLOAD, validate=True)
    if hashlib.sha256(raw).hexdigest() != CODE_SHA:
        raise RuntimeError("embedded code ZIP differs")
    root = Path("/content/muster_native_related_code") / CODE_SHA[:16]
    with zipfile.ZipFile(io.BytesIO(raw)) as z:
        info = json.loads(z.read("CODE_MANIFEST.json"))
        if set(z.namelist()) != set(info["files"]) | {"CODE_MANIFEST.json"}:
            raise RuntimeError("code inventory differs")
        for name, digest in info["files"].items():
            if Path(name).is_absolute() or ".." in Path(name).parts:
                raise RuntimeError("unsafe code path")
            value = z.read(name)
            if hashlib.sha256(value).hexdigest() != digest:
                raise RuntimeError("embedded module hash differs")
            p = root / name
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_bytes(value)
    return root, info


def run():
    if sys.platform != "linux" or not Path("/content").is_dir():
        raise RuntimeError("actual models run on Colab only")
    code, info = unpack()
    helper = module(code / "metadata/bootstrap_prepare.py", "_native_related_prepare")
    if not helper.drive_mounted():
        raise RuntimeError("Drive must be mounted before running")
    package = helper.prepare_package()
    output = helper.DRIVE_ROOT / "MUSTER_native_related_graphcap_20261116/results" / CODE_SHA[:16]
    output.mkdir(parents=True, exist_ok=True)
    cache = Path("/content/muster_assembly_parallel_assets/hf")
    helper.prepare_models(package, cache, output)
    if not helper.drive_mounted():
        raise RuntimeError("Drive is not mounted; no native job started")
    campaign = module(code / "metadata/campaign.py", "_native_related_campaign")
    config = {"schema": campaign.SCHEMA, "asset_dir": str(code), "output_dir": str(output),
        "local_dir": str(Path("/content/muster_native_related_work") / CODE_SHA[:16]),
        "models_cache": str(cache), "phases": [{"id": "related_3cohorts", "module": "related.py",
            "module_sha256": info["files"]["related.py"], "config": {
                "package_dir": str(helper.PACKAGE_ROOT), "output_dir": "{output}", "models_cache": "{cache}",
                "max_workers": 3,
                "baseline_dir": str(helper.DRIVE_ROOT / "MUSTER_native5_full3_static_20261115_v2/outputs/native-static-v1-718c6081b56e"),
                "native_module": "{asset}/metadata/native_fast.py", "patch_path": "{asset}/metadata/search_graphcap.py"}}]}
    print("RHELM 확장/비확장·CloneMem 3곳을 최대3프로세스로 실행합니다. 각200→400, 총5656문맥입니다.", flush=True)
    print("LME-v2는 실행·중단하지 않습니다. 답/judge API 0. 새 결과:", output, flush=True)
    result = campaign.run_campaign(config)
    print("관련 native 실행 상태:", result["status"], flush=True)
    print("질문별 seconds·CE pairs와 공유 GPU wall time을 구분하십시오. 답 정확도는 미측정입니다.", flush=True)
    return result


if __name__ == "__main__":
    raise SystemExit(0 if run()["status"] == "DONE" else 2)
